	/**
	* 刷新 Token
	* 只调用 accounts 刷新 Web Cookie，避免完整 getAccount 继续请求 billing 并递归触发 401。
	* @returns Promise<Account | null> 刷新后的账号信息
	*/
	async refreshToken() {
		console.log("[BackendProvider] Refreshing token...");
		try {
			const accounts = ((await withOnceConnectRetry(() => httpService.get("/console/accounts"))).data?.accounts || []).map(normalizeAccountAvatar);
			const currentAccount = accountService.getAccount();
			const account = accounts.find((candidate) => {
				if (!currentAccount) return false;
				if (candidate.uid !== currentAccount.uid || candidate.type !== currentAccount.type) return false;
				return candidate.type === "personal" || candidate.enterpriseId === currentAccount.enterpriseId;
			}) ?? (!currentAccount && accounts.length === 1 ? accounts[0] : void 0);
			if (!account) return null;
			const refreshedAccount = currentAccount ? {
				...currentAccount,
				...account
			} : account;
			accountService.setAccount(refreshedAccount);
			console.log("[BackendProvider] Token refreshed, account:", account?.uid);
			return refreshedAccount;
		} catch (error) {
			console.error("[BackendProvider] refreshToken failed:", error);
			return null;
		}
	}
